import { disabled, fieldSurface, focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const select = tv({
  slots: {
    trigger: [
      "relative inline-flex w-full min-w-40 cursor-pointer select-none items-center justify-between gap-3 text-left",
      fieldSurface,
      "transition-[translate,box-shadow] duration-70 ease-linear motion-reduce:transition-none",
      "active:translate-x-1 active:translate-y-1 active:shadow-none",
      "data-popup-open:translate-x-1 data-popup-open:translate-y-1 data-popup-open:shadow-none",
      focusRing,
      disabled,
    ],
    value: "truncate data-placeholder:text-disabled-foreground",
    icon: "flex shrink-0 items-center",
    positioner: "z-50 outline-none",
    popup: [
      "max-h-(--available-height) min-w-(--anchor-width) overflow-y-auto",
      "border-3 border-border bg-raised text-foreground shadow-lg outline-none",
    ],
    list: "py-1",
    item: [
      "relative flex min-h-11 cursor-pointer select-none items-center gap-3 px-3 font-medium outline-none",
      "data-highlighted:bg-secondary data-selected:font-bold",
      "data-disabled:cursor-not-allowed data-disabled:text-disabled-foreground",
    ],
    itemIndicator: "flex size-4 shrink-0 items-center justify-center",
    itemText: "flex-1",
    groupLabel: "px-3 pt-3 pb-1 font-mono text-xs font-bold uppercase",
    separator: "my-1 h-0.5 bg-border",
    label: "font-display text-sm font-bold uppercase tracking-wide text-foreground",
  },
  variants: {
    size: {
      sm: { trigger: "h-11 px-2.5 text-sm", item: "text-sm" },
      md: { trigger: "h-12 px-3 text-base", item: "text-base" },
      lg: { trigger: "h-14 px-4 text-lg", item: "text-lg" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type SelectVariants = VariantProps<typeof select>;

"use client";

import { Select as BaseSelect } from "@base-ui/react/select";
import { select, type SelectVariants } from "@/lib/beton/recipes/select.recipe";
import { createContext, useContext, type ReactNode } from "react";
import { CheckIcon, ChevronDownIcon } from "@/lib/beton/icons";

const SelectContext = createContext<NonNullable<SelectVariants["size"]>>("md");

function useStyles() {
  return select({ size: useContext(SelectContext) });
}

export type SelectProps<
  Value,
  Multiple extends boolean | undefined = false,
> = BaseSelect.Root.Props<Value, Multiple> & SelectVariants;

function SelectRoot<Value, Multiple extends boolean | undefined = false>({
  size = "md",
  ...props
}: SelectProps<Value, Multiple>) {
  return (
    <SelectContext.Provider value={size}>
      <BaseSelect.Root {...props} />
    </SelectContext.Provider>
  );
}

export interface SelectTriggerProps extends Omit<
  BaseSelect.Trigger.Props,
  "className" | "children"
> {
  className?: string;
  /** Shown when nothing is selected. */
  placeholder?: ReactNode;
  /** Custom rendering of the selected value. */
  children?: BaseSelect.Value.Props["children"];
}

function SelectTrigger({ className, placeholder, children, ...props }: SelectTriggerProps) {
  const styles = useStyles();
  return (
    <BaseSelect.Trigger {...props} className={styles.trigger({ class: className })}>
      <BaseSelect.Value className={styles.value()} placeholder={placeholder}>
        {children}
      </BaseSelect.Value>
      <BaseSelect.Icon className={styles.icon()}>
        <ChevronDownIcon width={18} height={18} />
      </BaseSelect.Icon>
    </BaseSelect.Trigger>
  );
}

export interface SelectContentProps extends Omit<BaseSelect.Popup.Props, "className"> {
  className?: string;
  side?: BaseSelect.Positioner.Props["side"];
  align?: BaseSelect.Positioner.Props["align"];
  sideOffset?: number;
  /** Overlap the trigger with the selected item, like a native select. Off by default. */
  alignItemWithTrigger?: boolean;
}

function SelectContent({
  className,
  children,
  side = "bottom",
  align = "start",
  sideOffset = 8,
  alignItemWithTrigger = false,
  ...props
}: SelectContentProps) {
  const styles = useStyles();
  return (
    <BaseSelect.Portal>
      <BaseSelect.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignItemWithTrigger={alignItemWithTrigger}
        className={styles.positioner()}
      >
        <BaseSelect.Popup {...props} className={styles.popup({ class: className })}>
          <BaseSelect.List className={styles.list()}>{children}</BaseSelect.List>
        </BaseSelect.Popup>
      </BaseSelect.Positioner>
    </BaseSelect.Portal>
  );
}

export interface SelectItemProps extends Omit<BaseSelect.Item.Props, "className"> {
  className?: string;
}

function SelectItem({ className, children, ...props }: SelectItemProps) {
  const styles = useStyles();
  return (
    <BaseSelect.Item {...props} className={styles.item({ class: className })}>
      <span className={styles.itemIndicator()}>
        <BaseSelect.ItemIndicator>
          <CheckIcon width={16} height={16} />
        </BaseSelect.ItemIndicator>
      </span>
      <BaseSelect.ItemText className={styles.itemText()}>{children}</BaseSelect.ItemText>
    </BaseSelect.Item>
  );
}

function SelectGroup(props: BaseSelect.Group.Props) {
  return <BaseSelect.Group {...props} />;
}

function SelectGroupLabel({
  className,
  ...props
}: Omit<BaseSelect.GroupLabel.Props, "className"> & { className?: string }) {
  return (
    <BaseSelect.GroupLabel {...props} className={useStyles().groupLabel({ class: className })} />
  );
}

function SelectSeparator({
  className,
  ...props
}: Omit<BaseSelect.Separator.Props, "className"> & { className?: string }) {
  return (
    <BaseSelect.Separator {...props} className={useStyles().separator({ class: className })} />
  );
}

function SelectLabel({
  className,
  ...props
}: Omit<BaseSelect.Label.Props, "className"> & { className?: string }) {
  return <BaseSelect.Label {...props} className={useStyles().label({ class: className })} />;
}

/** Choose one option, or several with `multiple`, from a list. */
export const Select = Object.assign(SelectRoot, {
  Label: SelectLabel,
  Trigger: SelectTrigger,
  Content: SelectContent,
  Item: SelectItem,
  Group: SelectGroup,
  GroupLabel: SelectGroupLabel,
  Separator: SelectSeparator,
});
